const prohibited = ['en el mundo de','cuando se trata de','es importante señalar','cabe destacar','en la era digital','hoy en día','en el dinámico mundo','en última instancia','soluciones a la medida','soluciones integrales','amplio portafolio','amplio catálogo','calidad garantizada','cumplir con las expectativas'];
const lowerBody = bodyText.toLowerCase();
