// v3 (adaptado de BC 2026-05-07): head bigram + stem 5 + containment 0.8 + slug 0.60
const currentKeyword = $('Leer Keywords Aprobadas').first().json.keyword || '';
const allItems = $input.all();

const publishedPosts = allItems
  .filter(i => i.json && i.json.keyword && i.json.url_post)
  .map(i => ({ keyword: i.json.keyword, url: i.json.url_post }));

const posts_contexto = publishedPosts.length > 0
  ? 'Posts publicados en Ferretería Ya (' + publishedPosts.length + ' artículos):\n'
    + publishedPosts.map(p => '- ' + p.keyword + ' → ' + p.url).join('\n')
  : 'No hay artículos publicados aún.';

// STOP: excluye 'como' (palabra distintiva SEO how-to). Sin términos de dominio ferretería para no perder señal.
const STOP = new Set([
  'de','la','el','en','y','para','un','una','con','del','los','las','que',
  'mi','tu','su','sus','mis','tus','es','se','no','al','lo','les','por',
  'mas','o','u','le','vs','sobre','entre','desde','hasta','hacia','sin',
  'muy','si','ser','hay','son','sea','sean','tambien','solo','este','esta',
  'esto','estos','estas','han','fue','era'
]);

function strip(s) {
  return (s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
}
function stem(t) { return t.length >= 5 ? t.slice(0, 5) : t; }
function tokList(s) {
  return strip(s).split(/[^a-z0-9]+/).filter(t => t.length > 2 && !STOP.has(t)).map(stem);
}
function toks(s) { return new Set(tokList(s)); }

function slugFromUrl(url) {
  const m = (url || '').match(/\/([^\/]+)\/?$/);
  return m ? m[1] : '';
}

function jaccard(a, b) {
  if (a.size === 0 || b.size === 0) return 0;
  const inter = [...a].filter(w => b.has(w)).length;
  const uni = new Set([...a, ...b]).size;
  return uni > 0 ? inter / uni : 0;
}

const KW_JACCARD = 0.35;
const KW_CONTAIN = 0.80;
const SLUG_JACCARD = 0.60;

const curHead = tokList(currentKeyword);
const curSet  = new Set(curHead);
const curSlugSet = toks(currentKeyword.replace(/\s+/g, '-'));

let cannibalism = false, similar_keyword = '', similar_url = '', similarity_pct = 0, match_reason = '';

for (const post of publishedPosts) {
  const postHead = tokList(post.keyword);
  const postSet  = new Set(postHead);
  const postSlugSet = toks(slugFromUrl(post.url));

  let bestForThisPost = 0;
  let reasonForThisPost = '';

  // 1) Head bigram check (atrapa duplicados con relleno editorial divergente)
  if (curHead.length >= 2 && postHead.length >= 2 &&
      curHead[0] === postHead[0] && curHead[1] === postHead[1]) {
    bestForThisPost = 100;
    reasonForThisPost = 'head_bigram';
  }

  // 2) Jaccard kw threshold
  const kwSim = jaccard(curSet, postSet);
  if (kwSim >= KW_JACCARD && Math.round(kwSim * 100) > bestForThisPost) {
    bestForThisPost = Math.round(kwSim * 100);
    reasonForThisPost = 'kw_' + bestForThisPost + 'pct';
  }

  // 3) Containment check (smaller set >=80% en larger)
  if (curSet.size && postSet.size) {
    const smaller = curSet.size <= postSet.size ? curSet : postSet;
    const larger  = curSet.size <= postSet.size ? postSet : curSet;
    const cont = [...smaller].filter(t => larger.has(t)).length / smaller.size;
    if (cont >= KW_CONTAIN && Math.round(cont * 100) > bestForThisPost) {
      bestForThisPost = Math.round(cont * 100);
      reasonForThisPost = 'cont_' + bestForThisPost + 'pct';
    }
  }

  // 4) Slug similarity (red secundaria)
  const slugSim = jaccard(curSlugSet, postSlugSet);
  if (slugSim >= SLUG_JACCARD && Math.round(slugSim * 100) > bestForThisPost) {
    bestForThisPost = Math.round(slugSim * 100);
    reasonForThisPost = 'slug_' + bestForThisPost + 'pct';
  }

  if (bestForThisPost > similarity_pct) {
    cannibalism = true;
    similar_keyword = post.keyword;
    similar_url = post.url;
    similarity_pct = bestForThisPost;
    match_reason = reasonForThisPost;
  }
}

return [{ json: {
  posts_contexto, cannibalism,
  similar_keyword, similar_url, similarity_pct, match_reason,
  current_keyword: currentKeyword
} }];

